mapper.select:
SELECT *
FROM reconciliation_cutoff
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND cutoff_id=#{cutoffId} FOR UPDATE

SELECT b.id, b.sku_id, b.on_hand_qty, b.reserved_qty, b.free_execution_claim_qty, k.serial_enabled
FROM stock_balance b JOIN sku k ON k.enterprise_id=b.enterprise_id
AND k.id=b.sku_id
WHERE b.enterprise_id=#{enterpriseId}
AND b.warehouse_id=#{warehouseId}
AND b.updated_at<#{cutoff}
ORDER BY b.id
LIMIT #{limit}

SELECT l.balance_id, l.on_hand_after, l.reserved_after
FROM stock_ledger l INNER JOIN (SELECT balance_id, MAX(balance_version) AS v
FROM stock_ledger
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND occurred_at<#{cutoff} GROUP BY balance_id) t ON l.balance_id=t.balance_id
AND l.balance_version=t.v
WHERE l.enterprise_id=#{enterpriseId}
AND l.warehouse_id=#{warehouseId}

SELECT balance_id, COUNT(*) AS serial_count
FROM local_serial
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND state IN ('HOLD_RECEIVED','AUTHORIZED','SEALED')
AND balance_id IS NOT NULL GROUP BY balance_id

SELECT source_service, command_id, business_effect_key, fact_kind, quantity, occurred_at
FROM source_execution_fact
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND occurred_at<#{cutoff}

SELECT source_service, command_id, business_effect_key, quantity, created_at
FROM stock_posting
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND created_at<#{cutoff}

mapper.insert:
INSERT INTO reconciliation_case (id, enterprise_id, warehouse_id, cutoff_id, case_type, discrepancy_code, scope_id, sku_id, expected_qty, actual_qty, state, evidence_ref, remediation_operation_id, approved_by, version, created_at, updated_at)
VALUES (#{id}, #{enterpriseId}, #{warehouseId}, #{cutoffId}, #{caseType}, #{code}, #{scopeId}, #{skuId}, #{expected}, #{actual}, 'OPEN', #{evidence}, NULL, NULL, 0, #{now}, #{now})
ON DUPLICATE KEY UPDATE updated_at=#{now}

mapper.select:
SELECT *
FROM reconciliation_case
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND cutoff_id=#{cutoffId}
ORDER BY case_type, scope_id

SELECT *
FROM reconciliation_case
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND cutoff_id=#{cutoffId}
AND id > #{page.id}
ORDER BY id LIMIT #{page.fetchLimit}

SELECT *
FROM reconciliation_case
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id} FOR UPDATE

SELECT *
FROM reconciliation_case
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND cutoff_id=#{cutoffId}
AND case_type=#{caseType}
AND scope_id=#{scopeId}

mapper.update:
UPDATE reconciliation_case
SET state=#{toState}, approved_by=#{approvedBy}, remediation_operation_id=#{operationId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}
AND version=#{expected}
AND state=#{fromState}

mapper.select:
SELECT id, version, case_type, scope_id, state
FROM reconciliation_case
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND cutoff_id=#{cutoffId}
AND state IN ('REMEDIATING','VERIFYING')
